<?php require 'includes/core.php';$u=require_user();$ref=$_GET['ref']??'';$s=db()->prepare('SELECT * FROM payments WHERE transaction_code=? AND user_id=?');$s->execute([$ref,$u['id']]);$pay=$s->fetch();if(!$pay)go('user/dashboard.php');layout_start('Pagamento concluído',$u);?><div class="card auth" style="text-align:center"><div style="font-size:55px">✅</div><h1>Pagamento simulado!</h1><p class="muted">Seu plano <strong><?=h($pay['plan_name'])?></strong> foi ativado por 30 dias.</p><p><strong>Valor:</strong> <?=money($pay['amount'])?><br><strong>Método:</strong> <?=h($pay['method'])?><br><strong>Código:</strong> <?=h($pay['transaction_code'])?></p><div class="notice-demo">Transação fictícia, sem movimentação financeira.</div><a class="btn block" href="<?=url('user/dashboard.php')?>">Ir para meu painel</a></div><?php layout_end();?>